const moeSections=[
 ['从普通前馈层认识专家与路由器',
 para('Transformer的前馈网络（FFN）对每个位置的隐藏向量做可学习变换。混合专家（Mixture of Experts，MoE）把这一变换替换成多组专家参数，并用路由器为每个位置选择部分专家。这里的token指一个位置上的隐藏向量，不是原始汉字或整个用户请求。',
 '专家通常仍是一份神经网络，例如一组前馈层；它不保证天然对应“数学专家”或“代码专家”。路由器依据当前向量算出每个专家的分数，再选择部分分支。不同层、不同位置可以作不同选择。MoE这一名称也不表示多个聊天Agent互相讨论，二者的执行对象和状态边界不同。',
 '本章先讲清一层的计算，再讲把专家放到不同设备会新增什么问题。实验故意用二维向量和三份小线性变换替代完整FFN，好让每次路由都能手算；它们没有经过训练，不提供语言模型质量结论。')+
 '<p>'+linkTo('transformer-block','先读注意力、残差与前馈层的位置')+'</p>'],
 ['总参数、激活参数与实际驻留是三笔账',
 para('假设一层有E个专家，每个专家P个参数，每个token只选择k个，那么专家总参数约EP，该token经过的专家参数约kP。共享注意力、路由器和其他层仍需另外计算，不能把整个模型的活跃参数机械地写成总参数乘k/E。',
 '参数稀疏激活并不等于所有权重只占k份显存。为了处理不同token，通常仍要在某处保有全部所需专家；专家并行把它们分到不同设备，换来通信和负载协调。若按需搬运权重，还要支付搬运与调度时间。KV缓存对应注意力的历史状态，也不会因为FFN只选少数专家就自动按k/E减少。',
 '增加专家数可扩大可学习参数空间，但时延还取决于路由开销、每个专家获得多少token、矩阵形状、通信与批内偏斜。用“只激活四分之一参数”直接承诺四倍吞吐，会漏掉这些实际工作。')],
 ['Top-k选谁，门控权重怎样算',
 para('logit是路由器给每个专家的未归一化分数。Top-k选出其中分数最高的k个；门控权重决定它们的输出如何加权。归一化是把这些正权重除以总和，使它们相加为1。本章明确采用：选Top-2，再仅在入选者中做softmax。分数相同按专家编号升序打破并列，方便复算；这不是所有训练实现的并列规则。')+
 knowledgeFormula('本章的门控定义','S = Top-2(z)；gₑ = exp(zₑ − maxₛ∈S zₛ) / Σₛ∈S exp(zₛ − maxₛ∈S zₛ)；y = Σₑ∈S gₑ·Eₑ(x)','Eₑ(x)是专家e对输入x的输出。先对全专家softmax再截断，与截断后重新归一化需要区分；本章采用入选后归一化。')+
 para('例：[ln3,0,−9]选专家0与1，两者指数比例3:1，权重为0.75和0.25；第三位虽然有非零的全量softmax概率，在本章入选集合里权重为0。若只是截掉第三位、不重新归一化，权重和会略小于1。真实模型还可能有缩放、共享专家或其他门控规则，阅读配置和实现时必须核对。',
 '本例拒绝非有限分数和错误的专家数量；并列[0,0,0]选[0,1]。确定性的编号顺序有助于教学与回归，却也可能在大量相同分数时集中负载。训练阶段需要检查路由分布，不能把“选择稳定”直接当成“分布合理”。')+
 code('核心路由 · 完整边界检查见实验','PYTHON','selected = sorted(range(len(logits)), key=lambda i: (-logits[i], i))[:k]\nmaximum = max(logits[i] for i in selected)\nterms = [math.exp(logits[i] - maximum) for i in selected]\nweights = [value / math.fsum(terms) for value in terms]')],
 ['按专家分组计算，再按原token身份合并',
 para('每个token选两个专家，四个token就产生八条专家分配。分发（dispatch）把输入按专家组织，专家批量计算后，合并（combine）把结果放回原token，并乘对应门控权重相加。中间顺序已经改变，因此每条分配要保留原token、所选槽位、专家、权重和返回位置。')+
 figure('v46-moe-routing-map','本章四个输入、八条分配及加权结果。两个执行进程故意逆序回包，仍按token/slot合并；不能把按专家排序后的相邻两项直接当成原token的一对结果。')+
 para('第0个输入x=[1,2]：专家0返回[1,2]，专家1返回[2,2]，所以y=0.75×[1,2]+0.25×[2,2]=[1.25,2]。其余三行也有独立手算结果。实验再故意按专家排好后每两项合并，得到另一份形状正确、数值错误的输出；只检查输出仍是[4,2]就会放过它。',
 '“每条分配恰好回来一次”与“一个token得到两个贡献”并不矛盾。去重身份是(token,slot)，不是只看token。父进程核对返回身份集合，拒绝重复回包，再按原位置累加。GPU上的并行散射合并还要处理冲突与同步，本地单进程收集器没有替它们提供并发正确性证据。')],
 ['容量限制：先数分配，再决定溢出怎么办',
 para('同一批的专家负载可能极不均匀。容量是允许一个专家处理的分配数量上限。为了说明边界，本章定义每专家容量C=ceil(α×T×k/E)，T为token数、E为专家数、k为每token选择数，α为容量因子。本例α=1、T=4、k=2、E=3，所以C=3；这是本章Top-2参考策略，不能替代其他实现的容量定义。')+
 figure('v46-moe-capacity','正常负载2/3/3，在容量3下全部保留；偏斜4/4/0，只能保留3/3/0。空闲专家2不能自动承接其他专家的工作，因为参数和路由语义不同。')+
 para('本章按输入token顺序准入，容量满后丢掉该专家贡献，不重新归一化剩余权重。偏斜输入全部选择专家0与1：前三个token各保留两项，最后token两项都丢，MoE分支输出为[0,0]。在带残差的完整块中可能还保有原输入，但这不意味着丢弃对模型质量无影响。',
 '其他方案可以提高容量、按不同优先级准入、重路由，或采用不丢弃的可变专家批量。它们分别改变内存、通信、计算形状或模型语义。无丢弃也仍需容纳最大负载；不能只删掉容量检查而不给缓冲与调度留预算。面试时先说自己采用的规则，再谈吞吐与质量取舍。')],
 ['负载均衡：分别看分数、分配和真正执行',
 para('平均每专家8/3条，并不说明每个专家都处理了8/3条。正常批的分配计数为[2,3,3]，偏斜批为[4,4,0]；容量准入后又成为[3,3,0]。路由分数分布、选择计数、保留计数、丢弃率和设备完成时间应分别观察。只看全局平均值，会掩盖最慢专家决定的等待。',
 '一种Switch风格的辅助统计写作E×ΣfₑPₑ，其中fₑ是本批Top-1选择专家e的比例，Pₑ是全专家softmax概率的批均值，训练时还会乘系数。本程序用它比较声明输入的集中程度，没有反向传播，也没有把Top-2容量计数混作这份Top-1统计。',
 '均衡项用于影响训练目标，不能替代真实容量控制或服务调度。即使计数相同，专家形状、精度、设备速度和通信位置不同，也可能完成时间不同。要判断瓶颈，应把每专家有效token数、计算时刻、发送/接收分割和等待放到同一轮时序中看。')],
 ['专家并行新增了哪些数据路径',
 para('专家并行（EP）按专家参数划分设备；张量并行（TP）则把一个算子或参数张量再分片。两者可以组合。若token当前所在设备没有目标专家，便要把隐藏向量送过去，算完后再送回原位置。多方按各自目标互相交换数据，常用All-to-All类通信表达；其分割与顺序必须与路由元数据一致。',
 '本章逻辑映射：专家0和2属于rank0，专家1属于rank1，token原位置用编号奇偶标记。八条分配中有五条跨逻辑rank。若每向量2维、每元素8字节，单方向有效载荷5×2×8=80字节，往返160字节。这不包含元数据、打包、对齐和协议开销；也不是本地进程队列实际搬运字节数。',
 '真实EP还要先交换或约定每个目的地的数量，再打包有效向量、执行交换、计算并逆向合并。发送方和接收方的分割对不上，会产生错误或等待；某专家少量token也可能让矩阵计算效率下降。总耗时不能把理论通信带宽乘数据量后直接替代，还要测小消息延迟、布局转换、重叠与最长路径。',
 '实验确实启动了两个本地执行进程，但token的原rank是声明元数据，所有任务由父进程分发。它验证身份与合并，不是两台机器、GPU专家并行或NCCL集合通信。走向目标集群时，要沿相同输入和输出判据补上真实交换、设备同步与时序证据。')+
 '<p>'+linkTo('tensor-parallel-math','比较张量并行中的分片与归约')+linkTo('training-communication','继续核对集合通信的参与与顺序契约')+'</p>'],
 ['运行两进程路由与容量反例',
 para('程序只用Python标准库，无模型下载与网络服务。专家是固定的2×2矩阵，路由分数为声明输入；实际子进程负责执行对应线性变换。先与独立手算比较，再改变容量、回包顺序与非法输入。')+
 operatorRun('moe_routing.py','moe-routing-run','python3 moe_routing.py --report moe-local.json')+
 table(['观察','独立结果','它证明什么'],[['正常输出四行','[1.25,2]；[2.25,0.5]；[1.5,−1.25]；[−0.5,1.75]','权重、专家与原位置对应'],['两个执行进程逆序回包','与串行及手算逐项相同','本例按身份合并有效'],['偏斜且容量3','保留6、丢2，最后分支输出0','准入规则确实改变计算'],['错误按相邻专家结果合并','形状仍[4,2]，数值不符','只验形状不能验业务语义'],['重复回复/非法分数/错误宽度','分别拒绝','不能把异常静默拼进有效结果']])],
 ['面试表达：从一层算到一组设备',
 table(['追问','回答中应连接的对象'],[['MoE为什么参数多但不全算','共享层、E份专家、k份激活和全部权重的驻留'],['路由具体做了什么','logit、Top-k、归一化范围、分配与合并身份'],['容量因子越大越好吗','丢弃、缓冲、计算量与质量，不只吞吐'],['专家很多，为什么仍慢','小矩阵、偏斜、打包、通信和最长设备路径'],['负载均衡损失够用吗','训练目标与运行时容量分别负责什么'],['怎样证明EP实现正确','与单进程参考比较所有位置，核对分割/身份/权重，再测真实通信']])+
 para('先用四个token解释完整一层，能够手算输出、发现错误合并和容量丢失，再把相同对象放到真实设备上。这样谈路由、算子与网络时，它们属于同一条数据路径；不会把三个熟悉名词拼成一个未经验证的系统。')+
 '<p>'+linkTo('operator-profiling','返回算子正确性与性能分析')+linkTo('inference-performance','把专家计算放回推理时延与吞吐预算')+'</p>']
];
articles.push({id:'moe-routing',number:'A3.8',module:'platform',title:'MoE路由与专家执行：从Top-k到分发、容量与合并',level:'原理 + 参考实现 + 两进程',minutes:40,edition:'稀疏专家',baseline:'Python 3.9+；固定线性专家与实际本地子进程，非GPU EP',tags:['MoE','Top-k','专家并行','容量'],desc:'先分清专家、路由器与门控，再用四个输入、八条分配手算输出，观察身份错配、容量丢失与通信数据账。',intro:'一份输出不仅要算对，还要回到正确的位置。沿同一批token把专家选择、计算和合并逐项连起来。',prereq:'先读Transformer前馈层、softmax、张量并行与集合通信；本章从概念开始，不要求已有MoE训练经验。',objectives:['区分总参数、活跃参数与驻留状态','手算Top-2、专家输出与原位置合并','解释容量、负载偏斜及EP通信的代价'],sections:moeSections,check:['入选后softmax和全量softmax截断差在哪里？','四个token为何有八条分配，去重身份是什么？','空闲专家为何不能自动执行其他专家的参数？','本地两个进程与真实GPU EP还差什么证据？'],exercise:['E=3、T=4、k=2、α=1，四个token都选专家0/1。按输入顺序准入且丢弃不重新归一化，专家容量、保留分配与最后token分支输出分别是什么？','容量ceil(8/3)=3，原负载[4,4,0]，保留[3,3,0]共6条、丢2条。最后token两条贡献均丢，MoE分支输出0。残差是否存在、丢弃如何影响质量要另看完整模型，不能从这个线性参考直接推断。'],related:['transformer-block','operator-profiling','tensor-parallel-math','training-communication','inference-performance'],refs:['moeMixtral','moeSwitch','moeMegablocks','moeTorchCollective'],textbook:true,updated:'2026.11.07'});
